// 閃卡事件處理
export function handleFlashcardEvents(target, renderCallback) {
  const d = target.dataset;

  // 切換級別
  if (d.fcTier) {
    currentTier = d.fcTier;
    currentCardIndex = 0;
    isFlipped = false;
    stopFlashcardAutoPlay();
    renderCallback();
    return true;
  }

  // 翻轉卡片
  if (d.fcFlip) {
    isFlipped = !isFlipped;
    renderCallback();
    return true;
  }

  // 發音單字 (標準 1.0x)
  if (d.fcSpeakWord) {
    playWord(d.fcSpeakWord, false);
    return true;
  }

  // 慢速發音單字 (0.65x)
  if (d.fcSpeakWordSlow) {
    playWord(d.fcSpeakWordSlow, true);
    return true;
  }

  // 發音例句 (標準)
  if (d.fcSpeakSentence) {
    playSentence(d.fcSpeakSentence, false);
    return true;
  }

  // 慢速發音例句 (0.75x)
  if (d.fcSpeakSentenceSlow) {
    playSentence(d.fcSpeakSentenceSlow, true);
    return true;
  }

  // 上一張卡片
  if (d.fcPrev) {
    if (currentCardIndex > 0) {
      currentCardIndex--;
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 下一張卡片
  if (d.fcNext) {
    const list = getFilteredCards();
    if (currentCardIndex < list.length - 1) {
      currentCardIndex++;
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 標記掌握狀態
  if (d.fcMark) {
    const list = getFilteredCards();
    const card = list[currentCardIndex];
    if (card) {
      if (masteryState[card.id] === d.fcMark) {
        delete masteryState[card.id];
      } else {
        masteryState[card.id] = d.fcMark;
      }
      saveMastery();
      renderCallback();
    }
    return true;
  }

  // 切換卡片篩選 (all, need_review, mastered)
  if (d.fcFilter) {
    cardFilterStatus = d.fcFilter;
    currentCardIndex = 0;
    isFlipped = false;
    renderCallback();
    return true;
  }

  // 洗牌隨機重排
  if (d.fcShuffle) {
    const list = getFilteredCards();
    if (list.length > 1) {
      currentCardIndex = Math.floor(Math.random() * list.length);
      isFlipped = false;
      renderCallback();
    }
    return true;
  }

  // 切換自動輪播
  if (d.fcToggleAutoplay) {
    if (isAutoPlaying) {
      stopFlashcardAutoPlay();
    } else {
      startFlashcardAutoPlay(renderCallback);
    }
    renderCallback();
    return true;
  }

  return false;
}

// 自動輪播聽讀定時器
function startFlashcardAutoPlay(renderCallback) {
  stopFlashcardAutoPlay();
  isAutoPlaying = true;

  autoPlayInterval = setInterval(() => {
    const list = getFilteredCards();
    if (!list.length) return;

    const card = list[currentCardIndex];
    if (!card) return;

    if (!isFlipped) {
      // 朗讀單字，隨後翻面
      playWord(card.word, false, {
        onEnd: () => {
          setTimeout(() => {
            isFlipped = true;
            renderCallback();
            // 朗讀例句
            const example = teachingCard(card).example;
            if (example) playSentence(example);
          }, 800);
        }
      });
    } else {
      // 已經在背面，翻回正面並切換下一張
      isFlipped = false;
      if (currentCardIndex < list.length - 1) {
        currentCardIndex++;
      } else {
        currentCardIndex = 0;
      }
      renderCallback();
      const nextCard = list[currentCardIndex];
      if (nextCard) {
        playWord(nextCard.word);
      }
    }
  }, 4800);
}

function stopFlashcardAutoPlay() {
  if (autoPlayInterval) {
    clearInterval(autoPlayInterval);
    autoPlayInterval = null;
  }
  isAutoPlaying = false;
  stopAudio();
}

export function handleFlashcardInput(target, renderCallback) {
  if (target && target.id === 'fc-search-input') {
    const caret = target.selectionStart;
    cardSearchKeyword = target.value;
    currentCardIndex = 0;
    isFlipped = false;
    renderCallback();
    const input = document.querySelector('#fc-search-input');
    input?.focus();
    if (caret !== null) input?.setSelectionRange(caret, caret);
    return true;
  }
  return false;
}
